package com.aaliyun.leadnews.search.service;
import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.search.domain.SearchHistory;import com.aaliyun.leadnews.search.mapper.SearchHistoryMapper;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service public class SearchHistoryService{private final SearchHistoryMapper mapper;public SearchHistoryService(SearchHistoryMapper m){mapper=m;}@Transactional public void remember(String keyword){Long user=UserContext.getUserId();if(user==null)return;String k=keyword.trim();SearchHistory h=new SearchHistory();h.setUserId(user);h.setKeyword(k);try{mapper.insert(h);}catch(DuplicateKeyException e){mapper.update(null,new LambdaUpdateWrapper<SearchHistory>().eq(SearchHistory::getUserId,user).eq(SearchHistory::getKeyword,k).setSql("updated_time = CURRENT_TIMESTAMP(3)"));}List<SearchHistory> rows=list();if(rows.size()>20)mapper.deleteByIds(rows.subList(20,rows.size()).stream().map(SearchHistory::getId).toList());}
 public List<SearchHistory> list(){Long user=requireUser();return mapper.selectList(new LambdaQueryWrapper<SearchHistory>().eq(SearchHistory::getUserId,user).orderByDesc(SearchHistory::getUpdatedTime).last("LIMIT 20"));}public void clear(){mapper.delete(new LambdaQueryWrapper<SearchHistory>().eq(SearchHistory::getUserId,requireUser()));}public void delete(Long id){Long user=requireUser();int n=mapper.delete(new LambdaQueryWrapper<SearchHistory>().eq(SearchHistory::getId,id).eq(SearchHistory::getUserId,user));if(n==0)throw new BusinessException(40400,"Search history not found");}private Long requireUser(){Long user=UserContext.getUserId();if(user==null)throw new BusinessException(40100,"Authentication required");return user;}}
